def parse_duration(s):
    import re
    match = re.fullmatch(r'(?:(\d+)h)?(?:(\d+)m)?(?:(\d+)s)?', s)
    if not match:
        return 0
    h, m, sec = match.groups()
    return (int(h) * 3600 if h else 0) + (int(m) * 60 if m else 0) + (int(sec) if sec else 0)

